media_type.script:
try {
    // 1. Parse the incoming macro string passed by Zabbix into an object
    var params = JSON.parse(value);

    // 2. Extract values cleanly from the mapped parameters
    var username = params.username;
    var api_key = params.api_key;
    var to = params.to;
    var message = params.message;

    // 3. Initialize the HTTP request instance
    var req = new HttpRequest();

    req.addHeader('Accept: application/json');
    req.addHeader('Content-Type: application/x-www-form-urlencoded');
    req.addHeader('apiKey: ' + api_key);

    // 4. Safely URL-encode payload values 
    var body = 'username=' + encodeURIComponent(username)
        + '&to=' + encodeURIComponent(to)
        + '&message=' + encodeURIComponent(message);

    Zabbix.log(4, 'AT request body: ' + body);
    Zabbix.log(4, 'AT api_key length: ' + (api_key ? api_key.length : 0));

    // 5. Fire off the POST request to Africa's Talking API
    var resp = req.post(
        'https://api.sandbox.africastalking.com/version1/messaging',
        body
    );

    Zabbix.log(4, 'AT raw response: ' + resp);

    // 6. Response Validation and Error Handling
    if (resp === null || resp === '') {
        throw 'Empty response from Africa\'s Talking — check network connectivity from Zabbix server container';
    }

    if (resp.indexOf('<!DOCTYPE') !== -1 || resp.indexOf('<html') !== -1) {
        throw 'Got HTML instead of JSON — wrong URL or blocked request: ' + resp.substring(0, 200);
    }

    if (resp.indexOf('authentication') !== -1 || resp.indexOf('invalid') !== -1) {
        throw 'Auth failed — api_key value received by script: [' + api_key + '] length: ' + (api_key ? api_key.length : 0);
    }

    var result;
    try {
        result = JSON.parse(resp);
    } catch (e) {
        throw 'JSON parse failed. Raw response: ' + resp;
    }

    if (!result.SMSMessageData) {
        throw 'No SMSMessageData in response: ' + resp;
    }

    var recipients = result.SMSMessageData.Recipients;
    if (!recipients || recipients.length === 0) {
        throw 'No recipients in response: ' + resp;
    }

    if (recipients[0].status !== 'Success') {
        throw 'Recipient status not Success: ' + recipients[0].status + ' full response: ' + resp;
    }

    return 'SMS sent successfully: ' + result.SMSMessageData.Message;

} catch (error) {
    Zabbix.log(3, 'Africa\'s Talking notification failed: ' + error);
    throw 'Notification failed: ' + error;
}

message_template.message:
DASHEN BANK ATM ALERT
ATM: {HOST.NAME}
Problem: {TRIGGER.NAME}
Severity: {TRIGGER.SEVERITY}
Time: {EVENT.DATE} {EVENT.TIME}
Please respond immediately.

DASHEN BANK ATM RESOLVED
ATM: {HOST.NAME}
Problem: {TRIGGER.NAME}
Resolved: {EVENT.RECOVERY.DATE} {EVENT.RECOVERY.TIME}
Duration: {EVENT.DURATION}

media_type.script:
var params;

try {
    params = JSON.parse(value);
} catch (e) {
    throw 'INPUT IS NOT JSON: ' + value;
}

var glpi_url      = params.glpi_url;
var app_token     = params.app_token;
var glpi_user     = params.glpi_user;
var glpi_password = params.glpi_password;
var subject       = params.subject        || '';
var host          = params.host           || '';
var event_date    = params.event_date     || '';
var event_id      = params.event_id       || '';
var glpi_ticket_id = params.glpi_ticket_id || ''; 
var severity       = params.severity       || '';
var vendor         = params.vendor         || 'Unknown';

var severity_map = {
    '0': 'Not classified',
    '1': 'Information',
    '2': 'Warning',
    '3': 'Average',
    '4': 'High',
    '5': 'Disaster'
};

// Natively maps Zabbix {EVENT.VALUE}: '0' indicates Recovery, '1' indicates Problem
var mode = 'problem';
if (params.mode === '0' || params.mode === 0 || String(params.mode).toLowerCase().indexOf('recovery') !== -1) {
    mode = 'recovery';
}

/* ── Session Init ───────────────────────────────────────────────────────── */
var init_req = new HttpRequest();
init_req.addHeader('Authorization: Basic ' + btoa(glpi_user + ':' + glpi_password));
init_req.addHeader('App-Token: ' + app_token);

var init_response = init_req.get(glpi_url + '/initSession');
var session_token;
try {
    session_token = JSON.parse(init_response).session_token;
} catch (e) {
    throw 'Failed parsing initSession response: ' + init_response;
}

if (!session_token) {
    throw 'Failed to obtain GLPI session token';
}

/* ── API Helpers ────────────────────────────────────────────────────────── */
function glpi_post(endpoint, body) {
    var r = new HttpRequest();
    r.addHeader('Content-Type: application/json');
    r.addHeader('Session-Token: ' + session_token);
    r.addHeader('App-Token: ' + app_token);
    var res = r.post(glpi_url + endpoint, JSON.stringify(body));
    try { return JSON.parse(res); } catch(err) { return {raw: res}; }
}

function glpi_put(endpoint, body) {
    var r = new HttpRequest();
    r.addHeader('Content-Type: application/json');
    r.addHeader('Session-Token: ' + session_token);
    r.addHeader('App-Token: ' + app_token);
    return JSON.parse(r.put(glpi_url + endpoint, JSON.stringify(body)));
}

function kill() {
    try {
        var r = new HttpRequest();
        r.addHeader('Session-Token: ' + session_token);
        r.addHeader('App-Token: ' + app_token);
        r.get(glpi_url + '/killSession');
    } catch (e) {}
}

/* ==========================================================
   PROCESSING ENGINE
   ========================================================== */
if (mode === 'recovery') {
    var tid = 0;

    if (glpi_ticket_id && glpi_ticket_id !== '{EVENT.TAGS.glpi_id}' && glpi_ticket_id.trim() !== '') {
        tid = parseInt(glpi_ticket_id.trim(), 10);
    }

    if (!tid || tid <= 0) {
        kill();
        return 'RECOVERY SKIPPED: Tag macro link not populated for event context: ' + event_id;
    }

    /* Post Solution Details */
    glpi_post('/Ticket/' + tid + '/ITILSolution', {
        input: {
            items_id:        tid,
            itemtype:        'Ticket',
            solutiontypes_id: 0,
            content: 'AUTOMATICALLY RESOLVED BY ZABBIX\n\nEvent ID: ' + event_id + '\nResolved at: ' + event_date
        }
    });

    /* Close Ticket */
    glpi_put('/Ticket/' + tid, { input: { status: 5 } });
    kill();
    return 'RECOVERY SUCCESS: Closed Ticket #' + tid;

} else { 
    /* PROBLEM GENERATION BLOCK */
    var result = glpi_post('/Ticket', {
        input: {
            name: '[ZABBIX-' + event_id + '] ' + subject,
            content: 'Host: ' + host +
                     '\nVendor: ' + vendor +
                     '\nProblem: ' + subject +
                     '\nSeverity: ' + (severity_map[severity] || 'Unknown') +
                     '\nTime: ' + event_date +
                     '\nEvent ID: ' + event_id,
            urgency: 3,
            impact: 3,
            priority: 3,
            type: 1,
            status: 1,
            itilcategories_id: 5,
            slas_id_ttr: 3,
            _groups_id_assign: 2
        }
    });

    var clean_new_id = result.id || (result.raw ? JSON.parse(result.raw).id : 0);
    kill();

    if (!clean_new_id) {
        throw 'GLPI Ticket creation failure.';
    }

    // Pass tracking tag to Zabbix memory layer
    var zabbix_response = {
        'tags': {
            'glpi_id': String(clean_new_id)
        }
    };

    return JSON.stringify(zabbix_response);
}
